describe("Cart.checkout()", () => {
  describe("price refresh", () => {
    it("uses refreshed prices in totals", async () => {
      const cart = new Cart();
      cart.add(product({ id: "a", unitPriceCents: 100 }), 2);
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(500),
      };
      const result = await cart.checkout({ priceFetcher });
      // Refreshed: 500 * 2 = 1000
      expect(result.totals.subtotalCents).toBe(1000);
      expect(result.lines[0]!.product.unitPriceCents).toBe(500);
    });

    it("works without priceFetcher (uses original prices)", async () => {
      const cart = new Cart();
      cart.add(product({ unitPriceCents: 300 }), 2);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(600);
    });
  });

  describe("inventory check", () => {
    it("passes when inventory is available", async () => {
      const cart = new Cart();
      cart.add(product(), 2);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      await expect(cart.checkout({ inventoryChecker })).resolves.toBeDefined();
      expect(inventoryChecker.check).toHaveBeenCalledWith("p1", 2);
    });

    it("throws InventoryError when not available", async () => {
      const cart = new Cart();
      cart.add(product({ id: "x" }), 3);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          reason: "discontinued",
        }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const ie = err as InventoryError;
        expect(ie.productId).toBe("x");
        expect(ie.requested).toBe(3);
        expect(ie.message).toBe("discontinued");
      }
    });

    it("throws InventoryError on partial-stock denial", async () => {
      const cart = new Cart();
      cart.add(product({ id: "p1" }), 10);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 5,
        }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const ie = err as InventoryError;
        expect(ie.productId).toBe("p1");
        expect(ie.requested).toBe(10);
        expect(ie.available).toBe(5);
      }
    });

    it("checks each product and fails on first denial", async () => {
      const cart = new Cart();
      cart.add(product({ id: "a" }), 1);
      cart.add(product({ id: "b" }), 1);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn()
          .mockResolvedValueOnce({ available: true })
          .mockResolvedValueOnce({ available: false, reason: "sold out" }),
      };
      await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(
        InventoryError,
      );
    });
  });

  describe("async tax provider", () => {
    it("uses async tax provider when supplied", async () => {
      const cart = new Cart({ region: "US-CA" });
      cart.add(product({ unitPriceCents: 1000 }), 1);
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const result = await cart.checkout({ asyncTaxProvider });
      // Tax = 10% of 1000 = 100
      expect(result.totals.taxCents).toBe(100);
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
    });

    it("applies discount before async tax", async () => {
      const discount = { computeDiscountCents: () => 200 };
      const cart = new Cart({ discountPolicy: discount });
      cart.add(product({ unitPriceCents: 1000 }), 1);
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const result = await cart.checkout({ asyncTaxProvider });
      // Discounted = 1000 - 200 = 800, tax = 10% of 800 = 80
      expect(result.totals.taxCents).toBe(80);
      expect(result.totals.discountCents).toBe(200);
    });

    it("propagates async tax provider error", async () => {
      const cart = new Cart();
      cart.add(product(), 1);
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
      };
      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
        "tax service down",
      );
    });
  });

  describe("full pipeline composition", () => {
    it("combines price refresh + inventory + async tax + discount + shipping", async () => {
      const discount = { computeDiscountCents: () => 100 };
      const shipping = { computeShippingCents: () => 250 };
      const cart = new Cart({
        discountPolicy: discount,
        shippingCalculator: shipping,
        region: "US",
      });
      cart.add(product({ id: "a", unitPriceCents: 500 }), 2);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(600),
      };
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 100 }),
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.05),
      };

      const result = await cart.checkout({
        priceFetcher,
        inventoryChecker,
        asyncTaxProvider,
      });

      // Refreshed subtotal: 600 * 2 = 1200
      expect(result.totals.subtotalCents).toBe(1200);
      // Discount: 100 (clamped within [0, 1200])
      expect(result.totals.discountCents).toBe(100);
      // Discounted subtotal: 1200 - 100 = 1100
      // Tax: 5% of 1100 = 55
      expect(result.totals.taxCents).toBe(55);
      // Shipping: 250
      expect(result.totals.shippingCents).toBe(250);
      // Total: 1100 + 55 + 250 = 1405
      expect(result.totals.totalCents).toBe(1405);
    });
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([
    [0],
    [1000],
    [999999],
    [-500],
  ])("computeDiscountCents(%i) returns 0", (subtotal) => {
    expect(policy.computeDiscountCents(subtotal)).toBe(0);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([
      [-1, "negative"],
      [101, "over 100"],
      [NaN, "NaN"],
      [Infinity, "Infinity"],
    ])("rejects %s (%s)", (percent) => {
      expect(() => new PercentageDiscountPolicy(percent)).toThrow(RangeError);
    });

    it.each([0, 50, 100])("accepts valid percent %i", (percent) => {
      expect(() => new PercentageDiscountPolicy(percent)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns 0 when subtotal is 0", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 when subtotal is negative", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(-1000)).toBe(0);
    });

    it("computes 10% of 1000 = 100", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(1000)).toBe(100);
    });

    it("rounds down fractional cents (10% of 999 = 99)", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(999)).toBe(99);
    });

    it("100% discount returns the entire subtotal", () => {
      const policy = new PercentageDiscountPolicy(100);
      expect(policy.computeDiscountCents(5000)).toBe(5000);
    });

    it("0% discount returns 0", () => {
      const policy = new PercentageDiscountPolicy(0);
      expect(policy.computeDiscountCents(5000)).toBe(0);
    });

    it("handles very large subtotals", () => {
      const policy = new PercentageDiscountPolicy(15);
      // 15% of 10_000_000 = 1_500_000
      expect(policy.computeDiscountCents(10_000_000)).toBe(1_500_000);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects negative amount", () => {
      expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
    });

    it("rejects non-integer amount", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

    it("accepts 0", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns 0 when subtotal is 0", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 when subtotal is negative", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("returns amount when subtotal exceeds it", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(1000)).toBe(500);
    });

    it("clamps to subtotal when amount exceeds subtotal", () => {
