    it("uses refreshed prices in totals", async () => {
      const cart = new Cart();
      cart.add(product({ id: "a", unitPriceCents: 100 }), 2);
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(500),
      };
      const result = await cart.checkout({ priceFetcher });
      // Refreshed: 500 * 2 = 1000
      expect(result.totals.subtotalCents).toBe(1000);
      expect(result.lines[0]!.product.unitPriceCents).toBe(500);
    });

    it("works without priceFetcher (uses original prices)", async () => {
      const cart = new Cart();
      cart.add(product({ unitPriceCents: 300 }), 2);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(600);
    });
  });

  describe("inventory check", () => {
    it("passes when inventory is available", async () => {
      const cart = new Cart();
      cart.add(product(), 2);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      await expect(cart.checkout({ inventoryChecker })).resolves.toBeDefined();
      expect(inventoryChecker.check).toHaveBeenCalledWith("p1", 2);
    });

    it("throws InventoryError when not available", async () => {
      const cart = new Cart();
      cart.add(product({ id: "x" }), 3);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          reason: "discontinued",
        }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const ie = err as InventoryError;
        expect(ie.productId).toBe("x");
        expect(ie.requested).toBe(3);
        expect(ie.message).toBe("discontinued");
      }
    });

    it("throws InventoryError on partial-stock denial", async () => {
      const cart = new Cart();
      cart.add(product({ id: "p1" }), 10);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 5,
        }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const ie = err as InventoryError;
        expect(ie.productId).toBe("p1");
        expect(ie.requested).toBe(10);
        expect(ie.available).toBe(5);
      }
    });

    it("checks each product and fails on first denial", async () => {
      const cart = new Cart();
      cart.add(product({ id: "a" }), 1);
      cart.add(product({ id: "b" }), 1);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn()
          .mockResolvedValueOnce({ available: true })
          .mockResolvedValueOnce({ available: false, reason: "sold out" }),
      };
      await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(
        InventoryError,
      );
    });
  });

  describe("async tax provider", () => {
    it("uses async tax provider when supplied", async () => {
      const cart = new Cart({ region: "US-CA" });
      cart.add(product({ unitPriceCents: 1000 }), 1);
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const result = await cart.checkout({ asyncTaxProvider });
      // Tax = 10% of 1000 = 100
      expect(result.totals.taxCents).toBe(100);
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
    });

    it("applies discount before async tax", async () => {
      const discount = { computeDiscountCents: () => 200 };
      const cart = new Cart({ discountPolicy: discount });
      cart.add(product({ unitPriceCents: 1000 }), 1);
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const result = await cart.checkout({ asyncTaxProvider });
      // Discounted = 1000 - 200 = 800, tax = 10% of 800 = 80
      expect(result.totals.taxCents).toBe(80);
      expect(result.totals.discountCents).toBe(200);
    });

    it("propagates async tax provider error", async () => {
      const cart = new Cart();
      cart.add(product(), 1);
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
      };
      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
        "tax service down",
      );
    });
  });

  describe("full pipeline composition", () => {
    it("combines price refresh + inventory + async tax + discount + shipping", async () => {
      const discount = { computeDiscountCents: () => 100 };
      const shipping = { computeShippingCents: () => 250 };
      const cart = new Cart({
        discountPolicy: discount,
        shippingCalculator: shipping,
        region: "US",
      });
      cart.add(product({ id: "a", unitPriceCents: 500 }), 2);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(600),
      };
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 100 }),
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.05),
      };

      const result = await cart.checkout({
        priceFetcher,
        inventoryChecker,
        asyncTaxProvider,
      });

      // Refreshed subtotal: 600 * 2 = 1200
      expect(result.totals.subtotalCents).toBe(1200);
      // Discount: 100 (clamped within [0, 1200])
      expect(result.totals.discountCents).toBe(100);
      // Discounted subtotal: 1200 - 100 = 1100
      // Tax: 5% of 1100 = 55
      expect(result.totals.taxCents).toBe(55);
      // Shipping: 250
      expect(result.totals.shippingCents).toBe(250);
      // Total: 1100 + 55 + 250 = 1405
      expect(result.totals.totalCents).toBe(1405);
    });
  });
});

