      const cart = new Cart();
      cart.add(product({ unitPriceCents: 300 }), 2);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(600);
    });
  });

  describe("inventory check", () => {
    it("passes when inventory is available", async () => {
      const cart = new Cart();
      cart.add(product(), 2);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      await expect(cart.checkout({ inventoryChecker })).resolves.toBeDefined();
      expect(inventoryChecker.check).toHaveBeenCalledWith("p1", 2);
    });

    it("throws InventoryError when not available", async () => {
      const cart = new Cart();
      cart.add(product({ id: "x" }), 3);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          reason: "discontinued",
        }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const ie = err as InventoryError;
        expect(ie.productId).toBe("x");
        expect(ie.requested).toBe(3);
        expect(ie.message).toBe("discontinued");
      }
    });

    it("throws InventoryError on partial-stock denial", async () => {
      const cart = new Cart();
      cart.add(product({ id: "p1" }), 10);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 5,
        }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const ie = err as InventoryError;
        expect(ie.productId).toBe("p1");
        expect(ie.requested).toBe(10);
        expect(ie.available).toBe(5);
      }
    });

    it("checks each product and fails on first denial", async () => {
      const cart = new Cart();
      cart.add(product({ id: "a" }), 1);
      cart.add(product({ id: "b" }), 1);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn()
          .mockResolvedValueOnce({ available: true })
          .mockResolvedValueOnce({ available: false, reason: "sold out" }),
      };
      await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(
        InventoryError,
      );
    });
  });

